input.newString:
const world={role:'survivor',running:false,started:0,elapsed:0,gensDone:0,health:'healthy',down:false,carried:false,escaped:false,over:false,score:0,repair:null,skill:false,skillAngle:0,skillTarget:0,attackCooldown:0,stamina:100,playerYaw:0,cameraYaw:0,cameraPitch:.22,gateProgress:0,gateOpen:false,noise:0,toastTimer:0,aiKills:0};
const keys={},clock=new THREE.Clock();let actionHold=false,moveX=0,moveY=0,lastSkill=0;
function announce(text){$('#toast').textContent=text;$('#toast').classList.add('show');world.toastTimer=2.2}
function start(role){world.role=role;world.running=true;world.started=performance.now();world.elapsed=0;world.gensDone=0;world.health='healthy';world.score=0;world.over=false;world.gateOpen=false;world.gateProgress=0;world.attackCooldown=0;world.stamina=100;world.noise=0;world.aiKills=0;for(let g of gens){g.progress=0;g.done=false;g.glow.intensity=0}for(let a of ai){a.state='idle';a.health='healthy';a.hookTime=0;a.mesh.visible=true}player.position.set(0,0,3);killer.position.set(4,0,8);for(let i=0;i<ai.length;i++){ai[i].x=Math.cos(i*1.57)*12;ai[i].z=Math.sin(i*1.57)*12;ai[i].mesh.position.set(ai[i].x,0,ai[i].z)}$('#menu').style.display='none';$('#hud').style.display='block';$('#mobile').style.display='block';$('#roleTag').textContent=role==='survivor'?'SURVIVOR':'THE WARDEN';$('#stateText').textContent='HEALTHY';$('#crosshair').style.display=role==='killer'?'block':'none';$('#actionBtn').textContent=role==='killer'?'Attack':'Sprint';if(innerWidth>700)$('#mobile').style.display='none';updateStates();cameraYaw=role==='survivor'?Math.PI:0;announce(role==='survivor'?'Five generators. Find the first.':'They are in the fog. Find them.');}
function updateStates(){let html='<div class="state you">'+(world.role==='survivor'?'Y':'W')+'</div>';for(let i=0;i<4;i++){let a=ai[i];html+=`<div class="state ${a.health==='down'?'down':''}" title="${a.health}">${i+1}<span style="background:${a.health==='down'?'#c84a3b':a.state==='hooked'?'#d8aa6a':'#81bd85'}"></span></div>`}$('#states').innerHTML=html}
$('#survivorMode').onclick=()=>{world.role='survivor';$('#survivorMode').classList.add('active');$('#killerMode').classList.remove('active')};$('#killerMode').onclick=()=>{world.role='killer';$('#killerMode').classList.add('active');$('#survivorMode').classList.remove('active')};$('#play').onclick=()=>start(world.role);$('#again').onclick=()=>{$('#result').style.display='none';$('#menu').style.display='flex';$('#hud').style.display='none';$('#mobile').style.display='none';world.running=false};
function endMatch(win,title,copy){world.over=true;world.running=false;$('#resultTitle').textContent=title;$('#resultEyebrow').textContent=win?'TRIAL COMPLETE':'THE FOG CLAIMS YOU';$('#resultCopy').textContent=copy;$('#resultGens').textContent=world.gensDone+' / 5';$('#resultTime').textContent=timeText(world.elapsed);$('#resultScore').textContent=world.score;$('#result').style.display='flex'}
function timeText(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0')}
function distance(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function nearest(){let p=world.role==='survivor'?player.position:killer.position,best=null,bd=4.2;for(let g of gens)if(!g.done){let d=distance(p,g.group.position);if(d<bd){bd=d;best={kind:'generator',obj:g,d}}}for(let palt of pallets)if(!palt.dropped){let d=distance(p,palt.group.position);if(d<bd){bd=d;best={kind:'pallet',obj:palt,d}}}for(let h of hooks){let d=distance(p,h.position);if(d<bd){bd=d;best={kind:'hook',obj:h,d}}}if(world.role==='killer'){for(let a of ai){if(a.state==='down'){let d=distance(p,a.mesh.position);if(d<bd){bd=d;best={kind:'capture',obj:a,d}}}}let d=Math.hypot(p.x,p.z+37);if(world.gensDone>=5&&d<bd)best={kind:world.gateOpen?'escape':'gate',obj:gate,d}}else if(world.gensDone>=5){let d=Math.hypot(p.x,p.z+37);if(d<bd)best={kind:world.gateOpen?'escape':'gate',obj:gate,d}}return best}
function promptFor(n){if(!n){$('#prompt').style.display='none';return}let label={generator:world.role==='survivor'?'Repair generator':'Damage generator',pallet:world.role==='survivor'?'Drop pallet':'Break pallet',hook:'Use capture hook',capture:'Pick up survivor',gate:'Open exit gate',escape:'Escape through gate'}[n.kind];if(n.kind==='hook'&&world.role==='survivor')return $('#prompt').style.display='none';$('#promptText').textContent=label;$('#prompt').style.display='block'}
function interact(){if(!world.running||world.skill)return;let n=nearest();if(!n){if(world.role==='killer')attack();return}if(world.role==='survivor'){if(n.kind==='generator'){world.repair=n.obj;announce('Repairing · watch for the skill check')}else if(n.kind==='pallet'){n.obj.dropped=true;n.obj.group.rotation.z=-Math.PI/2;world.score+=150;world.noise=1;announce('Pallet dropped · the route is blocked')}else if(n.kind==='gate'){world.gateProgress=0;announce('Opening the exit gate')}else if(n.kind==='escape'&&world.gateOpen){endMatch(true,'Escaped','You made it beyond the fog. The others are still out there.')}}else{if(n.kind==='generator'){n.obj.progress=Math.max(0,n.obj.progress-.18);n.obj.done=false;world.score+=80;announce('Generator damaged · progress regressing')}else if(n.kind==='pallet'){n.obj.dropped=true;n.obj.group.rotation.z=-Math.PI/2;announce('Pallet destroyed')}else if(n.kind==='capture'){n.obj.state='hooked';n.obj.hookTime=0;n.obj.mesh.position.set(n.obj.mesh.position.x,0,n.obj.mesh.position.z);n.obj.mesh.visible=false;world.aiKills++;world.score+=400;updateStates();announce('Survivor captured · pressure the others')}else if(n.kind==='gate'){world.gateProgress=0;announce('Opening the exit gate')}}}
function attack(){if(world.role!=='killer'||world.attackCooldown>0)return;world.attackCooldown=1.2;let closest=null,bd=3.1;for(let a of ai)if(a.state!=='hooked'&&a.state!=='escaped'){let d=distance(killer.position,a.mesh.position);if(d<bd){bd=d;closest=a}}if(closest){if(closest.health==='healthy'){closest.health='injured';announce('Hit confirmed · survivor injured')}else{closest.health='down';closest.state='down';announce('Survivor down · pick them up')}world.score+=closest.health==='down'?250:100;updateStates()}else announce('Attack missed · recover');}
function doSkill(){if(!world.skill)return;world.skill=false;$('#skill').style.display='none';let a=(world.skillAngle%(Math.PI*2)+Math.PI*2)%(Math.PI*2);let rel=(a-world.skillTarget+Math.PI*2)%(Math.PI*2);if(rel<.34||rel>Math.PI*2-.34){world.score+=80;world.repair.progress=Math.min(1,world.repair.progress+.055);announce('Great skill check + progress')}else{world.repair.progress=Math.max(0,world.repair.progress-.12);world.noise=2;announce('Missed skill check · Killer alerted');if(world.role==='survivor')killer.userData.alert=4}}
function setSkill(){world.skill=true;world.skillAngle=0;world.skillTarget=4.25;$('#skill').style.display='block';lastSkill=world.elapsed}

