const stick=$('#stick');let stickId=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);updateStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)updateStick(e)});function updateStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.39;moveX=THREE.MathUtils.clamp(dx/max,-1,1);moveY=THREE.MathUtils.clamp(dy/max,-1,1)}function clearStick(e){if(e.pointerId===stickId){stickId=null;moveX=moveY=0}}stick.addEventListener('pointerup',clearStick);stick.addEventListener('pointercancel',clearStick);
