from html.parser import HTMLParser
class Scripts(HTMLParser):
 def __init__(self): super().__init__(); self.capture=False; self.module=False; self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag=='script':
   self.capture=True; self.module=dict(attrs).get('type')=='module'; self.current=[]
 def handle_data(self,data):
  if self.capture and self.module:self.current.append(data)
 def handle_endtag(self,tag):
  if tag=='script' and self.capture:
   if self.module:self.parts.append(''.join(self.current))
   self.capture=False
p=Scripts();p.feed(open('index.html').read());print('\n'.join(p.parts))
