const target=(await (await fetch('http://127.0.0.1:9222/json')).json()).find(t=>t.type==='page');const ws=new WebSocket(target.webSocketDebuggerUrl);let id=0,waiters=new Map(),errors=[];ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);if(m.id&&waiters.has(m.id)){waiters.get(m.id)(m);waiters.delete(m.id)}});await new Promise(r=>ws.addEventListener('open',r,{once:true}));const send=(method,params={})=>new Promise(resolve=>{let i=++id;waiters.set(i,resolve);ws.send(JSON.stringify({id:i,method,params}))});const ev=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result.result.value;
await send('Runtime.enable');await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});
console.log('mobile HUD',await ev(`(()=>{const t=window.__gameTest;t.start('survivor');return {controls:getComputedStyle(document.querySelector('#mobile')).display,stick:document.querySelector('#stick').getBoundingClientRect().toJSON(),z:t.player.position.z}})()`));
